def flatten(content, role):
    if isinstance(content, str):
        return content
    out = []
    for b in content or []:
        t = b.get("type")
        if t == "text":
            out.append(b.get("text", ""))
        elif t == "thinking":
            continue  # skip raw thinking
        elif t in ("toolCall", "toolUse"):
            name = b.get("name", "?")
            args = b.get("arguments") or b.get("input") or {}
            try:
                brief = json.dumps(args, ensure_ascii=False)[:300]
            except Exception:
                brief = str(args)[:300]
            out.append(f"[toolCall {name} {brief}]")
        elif t in ("toolResult", "tool_output"):
            txt = b.get("text") or b.get("content") or ""
            if not isinstance(txt, str):
                txt = json.dumps(txt, ensure_ascii=False)
            if txt.strip():
                out.append(f"[toolResult {txt[:500]}]")
    return "\n".join(x for x in out if x)[:CAP]

def messages_from(path):
    msgs = []
    for line in open(path, encoding="utf-8", errors="replace"):
        line = line.strip()
        if not line:
            continue
        try:
            o = json.loads(line)
        except Exception:
            continue
        if o.get("type") != "message":
            continue
        m = o.get("message", {})
        role = m.get("role")
        if role not in ("user", "assistant"):
            continue
        text = flatten(m.get("content"), role)
        if not text.strip():
            continue
        msgs.append({
            "role": role,
            "content": text,
            "created_at": o.get("timestamp"),
            "message_kind": "user_query" if role == "user" else "assistant_step",
        })
    return msgs

def main():
    only = sys.argv[1] if len(sys.argv) > 1 else None
    ok = fail = skip = 0
    for uuid, path in MISSING.items():
        if only and uuid != only:
            continue
        sid = f"pi-{uuid}"
        try:
            api("POST", "/api/v1/sessions", {"session_id": sid})
        except Exception as e:
            print(f"  create {sid}: {e}", flush=True)
        msgs = messages_from(path)
        if not msgs:
            print(f"SKIP {sid}: no extractable messages", flush=True)
            skip += 1
            continue
        for i in range(0, len(msgs), BATCH):
            api("POST", f"/api/v1/sessions/{sid}/messages/batch",
                {"messages": msgs[i:i + BATCH]})
        try:
            api("POST", f"/api/v1/sessions/{sid}/commit", {"keep_recent_count": 0})
            ok += 1
            print(f"OK   {sid} ({len(msgs)} msgs)", flush=True)
        except Exception as e:
            fail += 1
            print(f"FAIL {sid}: {e}", flush=True)
    print(f"\ndone: ok={ok} fail={fail} skip={skip}")

if __name__ == "__main__":
    main()
